    return arguments
  end
  if type(arguments) == "string" and type(decode_json) == "function" then
    local decoded = decode_json(arguments)
    if type(decoded) == "table" then
      return decoded
    end
  end
  return {}
end

-- Transform OpenAI-wire messages into intent Messages with stable
-- traceId/eventId/eventIndex. `start_index` offsets the (0-based) event index so
-- the response phase continues after the request phase's events. Deterministic +
-- append-only ⟹ re-sent history yields identical ids ⟹ server-side idempotency.
-- `decode_json` (e.g. cjson.decode) parses tool-call arguments into the object the
-- server's tool_use block requires. Returns (intent_messages, produced_count).
function M.to_intent_messages(messages, trace_id, start_index, decode_json)
  local out = {}
  local base = math.floor(tonumber(start_index) or 0)
  -- Count ONLY reproducible events (text / tool_use / tool_result). This index space is what the
  -- next turn's re-sent history reproduces, so it must stay stable regardless of reasoning.
  local repro = 0
  -- Reasoning events emitted since the last reproducible one, so several in a row (e.g. an n>1
  -- completion) get distinct, ascending in-gap indices instead of colliding on one.
  local gap = 0
  local function push(role, content)
    local index = (base + repro) * M.EVENT_INDEX_STRIDE
    repro = repro + 1
    gap = 0
    out[#out + 1] = {
      role = role,
      content = content,
      traceId = trace_id,
      eventId = M.derive_event_id(trace_id, index),
      eventIndex = index,
    }
  end
  -- Reasoning does NOT advance `repro` (it never appears in re-sent history, so taking a reproducible
  -- slot would shift the following tool_use/text and break cross-phase eventId idempotency). It fills
  -- the gap just above the previous reproducible event, ascending: (base+repro-1)*STRIDE + 1 + gap —
  -- strictly after that event, strictly before the next reproducible one, distinct per reasoning block
  -- (gap), and off the stride grid so its derived eventId can't collide with a reproducible one.
  local function push_reasoning(text)
    local index = (base + repro - 1) * M.EVENT_INDEX_STRIDE + 1 + gap
    -- Only negative if reasoning is the trace's very first event (no prior reproducible event to
    -- sit after) — it has no valid slot before index 0, so skip rather than clamp into a used one.
    if index < 0 then return end
    gap = gap + 1
    out[#out + 1] = {
      role = "model",
      content = { type = "reasoning", content = text },
      traceId = trace_id,
      eventId = M.derive_event_id(trace_id, index),
      eventIndex = index,
    }
  end

  for _, m in ipairs(messages or {}) do
    if type(m) == "table" and m.role then
      local role = tostring(m.role)
      if role == "tool" and m.tool_call_id then
        -- OpenAI tool result -> tool_result block (TOOL_OUTPUT_TEXT). The server derives the
        -- signal from the block type, but rejects role "tool"; tool results ride under `developer`.
        push("developer", { type = "tool_result", tool_use_id = m.tool_call_id,
                            content = M.flatten_text(m.content) })
      else
        -- Chronological order within a model turn: reasoning first (REASONING_TEXT), then the
        -- answer text (USER_MESSAGE / MODEL_RESPONSE), then any tool calls. Reasoning is a COMPLETION
        -- signal — only the model's own turn carries it — so gate it on the assistant/model role;
        -- a user/developer message with a stray reasoning field must not synthesize one. It rides
        -- under role `model` (the server derives the signal from the block type).
        if role == "assistant" or role == "model" then
          local reasoning = M.reasoning_text(m)
          if reasoning and reasoning ~= "" then
            push_reasoning(reasoning)
          end
        end
        -- Text first (USER_MESSAGE / MODEL_RESPONSE), then any tool calls.
        local text = M.flatten_text(m.content)
        if text ~= nil and text ~= "" then
          push(role, text)
        end
        if type(m.tool_calls) == "table" then
          for _, tc in ipairs(m.tool_calls) do
            local fn = type(tc) == "table" and tc["function"] or nil
            if type(fn) == "table" and fn.name then
              -- OpenAI tool call -> tool_use block (TOOL_INPUT_TEXT) under role `model`.
              -- `arguments` is a JSON string on the wire; the server's tool_use block requires
              -- an object, so decode it.
              push("model", { type = "tool_use", id = tc.id, name = fn.name,
                              input = tool_input_object(fn.arguments, decode_json) })
            end
          end
        end
      end
    end
  end
  -- Second return is the count of REPRODUCIBLE events (indices consumed) — the start offset the
  -- response phase continues from. Excludes reasoning, which consumes no reproducible index.
  return out, repro
end

-- Convert OpenAI tool definitions ({type="function", function={name,description,parameters}})
-- into the server's flat AvailableTool shape ({name, description, parameters}). Tools already in
-- the flat shape pass through; entries without a string name are dropped. Returns nil when there
-- is nothing to forward, so build_payload omits the field.
function M.to_intent_tools(tools)
  if type(tools) ~= "table" then
    return nil
  end
  local out = {}
  for _, t in ipairs(tools) do
    if type(t) == "table" then
      local fn = type(t["function"]) == "table" and t["function"] or t
      if type(fn.name) == "string" and fn.name ~= "" then
        out[#out + 1] = { name = fn.name, description = fn.description, parameters = fn.parameters }
      end
    end
  end
  if #out == 0 then
    return nil
  end
  return out
end

-- Block if any finding across any deputy has action == "BLOCK". Returns (blocked, detail).
function M.extract_block(findings)
  local details = {}
  for deputy, list in pairs(findings or {}) do
    if type(list) == "table" then
      for _, f in ipairs(list) do
        if type(f) == "table" and f.action == "BLOCK" then
          local name = f.name or "violation"
          local sev = f.severity and (" (" .. f.severity .. ")") or ""
          details[#details + 1] = deputy .. "/" .. name .. sev
        end
      end
    end
  end
  if #details > 0 then
    return true, table.concat(details, "; ")
  end
  return false, nil
end

-- Apply masking spans to a single content string. Lasso start/end are 0-based, end-exclusive
-- byte offsets; apply highest-first so earlier offsets stay valid.
local function apply_spans_to_text(content, spans)
  table.sort(spans, function(a, b) return a.start > b.start end)
  for _, s in ipairs(spans) do
    if s.start >= 0 and s["end"] > s.start and s["end"] <= #content then
      content = content:sub(1, s.start) .. s.mask .. content:sub(s["end"] + 1)
    end
  end
  return content
end

-- Redact AUTO_MASKING findings in-place on the messages table.
-- Prefers Lasso's top-level masked `messages` (authoritative) when present and shaped the
-- same; otherwise applies per-finding start/end/mask spans. Only AUTO_MASKING findings are
-- masked — alert/off findings can carry span metadata but must not be redacted.
-- Returns (messages, transformed).
function M.apply_masks(messages, resp)
  resp = resp or {}

  -- 1) authoritative masked messages from /classifix
  local masked = resp.messages
  if type(masked) == "table" and #masked == #messages and #messages > 0 then
    local transformed = false
    for i = 1, #messages do
      local new_content = masked[i] and masked[i].content
      if new_content ~= nil and tostring(new_content) ~= tostring(messages[i].content) then
        messages[i].content = new_content
        transformed = true
      end
    end
    if transformed then
      return messages, true
    end
  end

  -- 2) fall back to per-finding spans
  local by_index = {}
  for _, list in pairs(resp.findings or {}) do
    if type(list) == "table" then
      for _, f in ipairs(list) do
        if type(f) == "table" and f.action == "AUTO_MASKING"
           and f.start ~= nil and f["end"] ~= nil and f.mask then
          local mi = (f.message_index or 0) + 1  -- Lasso is 0-based; Lua is 1-based
          by_index[mi] = by_index[mi] or {}
          local spans = by_index[mi]
          spans[#spans + 1] = { start = f.start, ["end"] = f["end"], mask = f.mask }
        end
      end
    end
  end

  local transformed = false
  for mi, spans in pairs(by_index) do
    local msg = messages[mi]
    if msg and msg.content ~= nil then
      local original = tostring(msg.content)
      local updated = apply_spans_to_text(original, spans)
      if updated ~= original then
        msg.content = updated
        transformed = true
      end
    end
  end
  return messages, transformed
end

-- Decide the outcome of a classify/classifix response given the plugin config.
-- Returns a table: { action = "allow"|"block"|"mask", detail = <string?>, transformed = <bool> }
-- `messages` is mutated in place when action == "mask".
function M.decide(resp, messages, masking)
  resp = resp or {}
  if not resp.violations_detected then
    return { action = "allow" }
  end
  local blocked, detail = M.extract_block(resp.findings)
  if blocked then
    return { action = "block", detail = detail }   -- block trumps mask
  end
  if masking then
    local _, transformed = M.apply_masks(messages, resp)
    if transformed then
      return { action = "mask", transformed = true }
    end
  end
  -- AUTO_MASKING with masking off, or USER_ALERT / ADMIN_ALERT / OFF -> non-blocking.
  return { action = "allow" }
end

return M
end)()
local client = (function()
-- ── inlined from kong/plugins/ai-lasso-guardrail/client.lua ──
-- Thin HTTP client for the Lasso classify/classifix API. Kept small on purpose: all the
-- logic worth testing lives in lasso.lua; this only does transport + (de)serialization,
-- which is exercised under Pongo integration rather than plain-Lua unit tests.

local http = require "resty.http"
local cjson = require "cjson.safe"

local Client = {}

-- Returns (data, err_kind, status):
--   data      decoded response table on success, else nil
--   err_kind  nil | "auth" | "http" | "conn" | "parse"
--   status    HTTP status when there was a response
function Client.call(conf, endpoint, payload)
  local httpc = http.new()
  httpc:set_timeout(conf.timeout or 10000)

  local base = (conf.lasso_api_base or ""):gsub("/+$", "")
  local res, err = httpc:request_uri(base .. "/" .. endpoint, {
    method = "POST",
    body = cjson.encode(payload),
    headers = {
      ["Content-Type"] = "application/json",
      ["lasso-api-key"] = conf.lasso_api_key,
    },
    ssl_verify = conf.ssl_verify ~= false,
    keepalive_timeout = 60000,
  })

  if not res then
    return nil, "conn", nil, err
  end
  -- Auth/config errors are surfaced regardless of fail-mode (see handler): a bad key must
  -- not be silently swallowed by fail-open.
  if res.status == 401 or res.status == 403 then
    return nil, "auth", res.status
  end
  if res.status < 200 or res.status >= 300 then
    return nil, "http", res.status
  end

  local data = cjson.decode(res.body or "")
  if type(data) ~= "table" then
    return nil, "parse", res.status
  end
  return data, nil, res.status
end

return Client
end)()
local cjson = require "cjson.safe"

local AiLassoGuardrail = {
  -- Above ai-proxy (770) so we see and can mutate the original chat body before it proxies.
  PRIORITY = 772,
  VERSION = "1.1.0",
}

-- Flatten OpenAI multimodal content (string | array of blocks) to text for classification.
local function flatten_content(content)
  if type(content) == "string" then
    return content, true       -- maskable: it's a plain string we can write back to
  end
  if type(content) == "table" then
    local parts = {}
    for _, block in ipairs(content) do
      if type(block) == "table" and block.type == "text" and block.text then
        parts[#parts + 1] = block.text
      end
    end
    return table.concat(parts, " "), false  -- non-string content: scan text, don't mask back
  end
  return "", false
end

-- Build the scan list (what we send to Lasso) from OpenAI-style messages, remembering which
-- original entries are plain strings so masks can be written back only to those.
local function scan_messages_from_request(messages)
  local scan, meta = {}, {}
  for i, m in ipairs(messages or {}) do
    if type(m) == "table" and m.role and m.content ~= nil then
      local text, maskable = flatten_content(m.content)
      scan[#scan + 1] = { role = tostring(m.role), content = text }
      meta[#scan] = { orig = i, maskable = maskable }
    end
  end
  return scan, meta
end

local function scan_messages_from_response(choices)
  local scan, meta = {}, {}
  for i, c in ipairs(choices or {}) do
    local msg = type(c) == "table" and c.message or nil
    if type(msg) == "table" and msg.content ~= nil then
      scan[#scan + 1] = { role = msg.role or "assistant", content = tostring(msg.content) }
      meta[#scan] = { orig = i }
    end
  end
  return scan, meta
end

local function session_id(conf)
  local shared = kong.ctx.shared
  if not shared.lasso_session_id then
    -- Prefer a client-supplied conversation id (Kong has none of its own), so multi-turn
    -- calls sharing that header aggregate into one Lasso dialogue. Fall back to a generated
    -- ULID, which still groups the prompt+completion of this single request.
    local from_header
    if conf.session_header and conf.session_header ~= "" then
      from_header = kong.request.get_header(conf.session_header)
    end
    if from_header and from_header ~= "" then
      shared.lasso_session_id = from_header
    else
      shared.lasso_session_id = lasso.gen_ulid()
    end
  end
  return shared.lasso_session_id
end

local function resolve_user_id(conf)
  if conf.user_header and conf.user_header ~= "" then
    local hv = kong.request.get_header(conf.user_header)
    if hv and hv ~= "" then
      return hv
    end
  end
  local consumer = kong.client.get_consumer()
  if consumer then
    return consumer.username or consumer.id
  end
  return nil
end

-- Free-text headers are percent-encoded only when non-ASCII (flagged by the marker header);
-- decode iff flagged, since a raw ASCII value may legitimately contain '%'. Same convention the
-- intent/name headers use.
local function pct_decoded(conf, value)
  if value and kong.request.get_header(conf.intent_encoding_header) == "pct" then
    return ngx.unescape_uri(value)
  end
  return value
end

-- Resolve one agent-identity field for the classify payload: the per-request header (name is
-- configurable, like user_header/session_header) over the static config value, sanitized.
-- Returns nil when neither yields a usable value, so the field is omitted.
local function agent_identity(conf, header_name, conf_value, field)
  local raw
  if header_name and header_name ~= "" then
    raw = pct_decoded(conf, kong.request.get_header(header_name))
  end
  local value, header_rejected = lasso.resolve_agent_identity(raw, conf_value)
  if header_rejected then
    kong.log.warn("lasso guardrail: ignoring ", header_name, " — not a valid agent identity (max ",
      lasso.AGENT_IDENTITY_MAX_LENGTH, " bytes, no control or formatting characters)")
  end
  -- A configured value that never makes it through is a misconfiguration, not client input: say so
  -- rather than leaving the route silently unattributed.
  if not value and conf_value and conf_value ~= "" then
    kong.log.warn("lasso guardrail: ignoring configured ", field, " — not a valid agent identity")
  end
  return value
end

-- Run one classify/classifix call. Returns a decision table from lasso.decide, or one of
-- the control strings "allow" / "surface-auth" / "fail". Mutates `scan` on mask.
local function classify(conf, scan, tools, source)
  if #scan == 0 then
    return { action = "allow" }        -- nothing to classify; must not error
  end
  local dir = lasso.direction(source)
  local payload = lasso.build_payload({
    messages = scan,
    message_type = dir.message_type,
    session_id = session_id(conf),
    user_id = resolve_user_id(conf),
    tools = tools,
    source_type = conf.source_type,
    agent_id = agent_identity(conf, conf.agent_id_header, conf.agent_id, "agent_id"),
    agent_name = agent_identity(conf, conf.agent_name_header, conf.agent_name, "agent_name"),
  })
  local endpoint = conf.masking and "classifix" or "classify"
  local data, err_kind = client.call(conf, endpoint, payload)
  if err_kind == "auth" then
    return { action = "surface-auth" }
  elseif err_kind then
    return { action = "fail", err = err_kind }
  end
  return lasso.decide(data, scan, conf.masking)
end

local function fail_or_allow(conf, err)
  if conf.fail_open then
    kong.log.warn("lasso guardrail: Lasso unavailable (", err, ") — fail-open, allowing")
    return  -- pass through
  end
  kong.log.err("lasso guardrail: Lasso unavailable (", err, ") — fail-closed, blocking")
  return kong.response.exit(503, { message = "Guardrail unavailable" })
end

local function surface_auth()
  -- A bad/expired key is a misconfiguration; surface it (block) regardless of fail-mode so
  -- fail-open can't silently disable the guardrail forever.
  kong.log.err("lasso guardrail: Lasso auth error — check lasso_api_key")
  return kong.response.exit(500, { message = "Guardrail misconfigured" })
end

-- ── Intent double-duty ──────────────────────────────────────────────────────
-- When intent mode is on and the app seeded a per-turn traceId header, the
-- existing access/response classify calls also feed the intent trace. The app
-- contributes only the traceId; Kong turns each phase's messages into intent
-- events (stable ids via lasso.to_intent_messages) on the SAME classify that
-- enforces content-safety. No separate call, no assembled trace.

-- The per-turn traceId the app seeded, or nil when intent is off / not seeded.
local function intent_trace_id(conf)
  if not conf.intent then
    return nil
  end
  local tid = kong.request.get_header(conf.intent_trace_header)
  if tid and tid ~= "" then
    return tid
  end
  return nil
end

local function intent_session_information(conf)
  local app_intent = kong.request.get_header(conf.intent_app_intent_header)
  -- applicationIntent is required for sessionInformation, so it gates the whole block.
  if not app_intent or app_intent == "" then
    return nil
  end
  -- Free-text headers are percent-encoded only when non-ASCII (flagged by the marker);
  -- decode iff flagged (a raw ASCII value may legitimately contain '%').
  local encoded = kong.request.get_header(conf.intent_encoding_header) == "pct"
  local function decode(value)
    if encoded and value then
      return ngx.unescape_uri(value)
    end
    return value
  end
  local info = { applicationIntent = decode(app_intent) }
  -- Optional display name so the trace shows up named in the intent UI (else it's unnamed).
  local app_name = kong.request.get_header(conf.intent_app_name_header)
  if app_name and app_name ~= "" then
    info.agenticAppName = decode(app_name)
  end
  return info
end

-- Run one intent-enriched classify (content-safety + intent) for a set of intent
-- messages. Returns a control string when the caller must exit, else nil (allow).
local function classify_intent(conf, messages, message_type, session_information, tools)
  if #messages == 0 then
    return nil
  end
  local payload = lasso.build_payload({
    messages = messages,
    message_type = message_type,
    session_id = session_id(conf),
    user_id = resolve_user_id(conf),
    tools = tools,
    source_type = conf.source_type,
    session_information = session_information,
    agent_id = agent_identity(conf, conf.agent_id_header, conf.agent_id, "agent_id"),
    agent_name = agent_identity(conf, conf.agent_name_header, conf.agent_name, "agent_name"),
  })
  -- Always /classify in intent mode: masking body-rewrite is out of scope here
  -- (detect/block still enforced from the findings).
  local data, err_kind = client.call(conf, "classify", payload)
  if err_kind == "auth" then
    return surface_auth()
  elseif err_kind then
    return fail_or_allow(conf, err_kind)
  end
  local decision = lasso.decide(data, messages, false)
  if decision.action == "block" then
    return kong.response.exit(conf.block_status_code,
      { message = conf.block_message, reason = decision.detail })
  end
  return nil
end

local function access_intent(conf, body, trace_id)
  local messages, count = lasso.to_intent_messages(body.messages, trace_id, 0, cjson.decode)
  -- The response phase continues the event index right after the request's events.
  kong.ctx.shared.lasso_intent_count = count
  return classify_intent(conf, messages, "PROMPT", intent_session_information(conf),
    lasso.to_intent_tools(body.tools))
end

local function response_intent(conf, trace_id)
  local raw = kong.service.response.get_raw_body()
  if not raw then
    return nil
  end
  local body = cjson.decode(raw)
  if type(body) ~= "table" or type(body.choices) ~= "table" then
    return nil
  end
  local completion = {}
  local terminal = false
  for _, c in ipairs(body.choices) do
    if type(c) == "table" and type(c.message) == "table" then
      completion[#completion + 1] = c.message
      -- finish_reason "stop" = a plain answer with no further tool calls: the turn is done.
      if c.finish_reason == "stop" then
        terminal = true
      end
    end
  end
  local start = kong.ctx.shared.lasso_intent_count or 0
  local messages = lasso.to_intent_messages(completion, trace_id, start, cjson.decode)
  -- Finalize the trace the moment the turn produces its terminal answer, so the server scores it
  -- now instead of after the server's inactivity timeout. Tool-call turns (finish_reason "tool_calls")
  -- are not marked, so a trace still mid-loop keeps accumulating.
  if conf.intent_finalize_on_stop ~= false and terminal and #messages > 0 then
    messages[#messages].isLastEventInTrace = true
  end
  return classify_intent(conf, messages, "COMPLETION", nil, nil)
end

function AiLassoGuardrail:access(conf)
  -- Intent double-duty: when seeded, this replaces the plain content-safety call
  -- (it enforces block AND feeds intent on one classify).
  local trace_id = intent_trace_id(conf)
  if trace_id then
    local ibody = kong.request.get_body()
    if type(ibody) == "table" and type(ibody.messages) == "table" then
      return access_intent(conf, ibody, trace_id)
    end
    return
  end

  if not conf.guard_request then
    return
  end
  local body = kong.request.get_body()
  if type(body) ~= "table" or type(body.messages) ~= "table" then
    return  -- not a chat body we understand; let ai-proxy handle it
  end

  local scan, meta = scan_messages_from_request(body.messages)
  local decision = classify(conf, scan, body.tools, "INPUT")

  if decision.action == "surface-auth" then
    return surface_auth()
  elseif decision.action == "fail" then
    return fail_or_allow(conf, decision.err)
  elseif decision.action == "block" then
    return kong.response.exit(conf.block_status_code,
      { message = conf.block_message, reason = decision.detail })
  elseif decision.action == "mask" then
    for i, m in ipairs(scan) do
      if meta[i] and meta[i].maskable then
        body.messages[meta[i].orig].content = m.content
      end
    end
    local ok, encoded = pcall(cjson.encode, body)
    if ok then
      kong.service.request.set_raw_body(encoded)
    else
      kong.log.err("lasso guardrail: failed to re-encode masked request body")
    end
  end
end

-- Defining :response triggers buffered proxying (disables streaming for the route), which is
-- what lets us read + rewrite the full completion. Streaming output is therefore out of scope.
function AiLassoGuardrail:response(conf)
  -- Intent double-duty: capture the completion (the final answer + any tool-call
  -- decision) as intent events, continuing the request phase's event index.
  local trace_id = intent_trace_id(conf)
  if trace_id then
    return response_intent(conf, trace_id)
  end

  if not conf.guard_response then
    return
  end
  local raw = kong.service.response.get_raw_body()
  if not raw then
    return
  end
  local body = cjson.decode(raw)
  if type(body) ~= "table" or type(body.choices) ~= "table" then
    return
  end

  local scan, meta = scan_messages_from_response(body.choices)
  local decision = classify(conf, scan, nil, "OUTPUT")

  if decision.action == "surface-auth" then
    return surface_auth()
  elseif decision.action == "fail" then
    return fail_or_allow(conf, decision.err)
  elseif decision.action == "block" then
    return kong.response.exit(conf.block_status_code,
      { message = conf.block_message, reason = decision.detail })
  elseif decision.action == "mask" then
    for i, m in ipairs(scan) do
      local choice = body.choices[meta[i].orig]
      if choice and choice.message then
        choice.message.content = m.content
      end
    end
    local ok, encoded = pcall(cjson.encode, body)
    if ok then
      -- Replace the buffered response with the masked body. We use kong.response.exit
      -- (allowed in the response phase) rather than set_raw_body (body_filter-only), so
      -- the whole rewrite happens in one phase before headers are flushed.
      return kong.response.exit(kong.response.get_status(), encoded,
        { ["Content-Type"] = "application/json" })
    else
      kong.log.err("lasso guardrail: failed to re-encode masked response body")
    end
  end
end

return AiLassoGuardrail
